1	export interface Logger {
2	  debug(category: string, message: string, fields?: Record<string, unknown>): void;
3	  info(category: string, message: string, fields?: Record<string, unknown>): void;
4	  warn(category: string, message: string, fields?: Record<string, unknown>): void;
5	  error(category: string, message: string, fields?: Record<string, unknown>): void;
6	}
7	
8	const LOG_LEVELS = {DEBUG: 0, INFO: 1, WARN: 2, ERROR: 3} as const;
9	type LevelName = keyof typeof LOG_LEVELS;
10	
11	const METHODS = {DEBUG: 'debug', INFO: 'info', WARN: 'warn', ERROR: 'error'} as const;
12	
13	const resolvedLevel = (() => {
14	  const env = (process.env.LOG_LEVEL || 'info').toUpperCase();
15	  return LOG_LEVELS[env as LevelName] ?? LOG_LEVELS.INFO;
16	})();
17	
18	export const UNSERIALISABLE = '[unserialisable]';
19	
20	function emit(level: LevelName, category: string, message: string, fields?: Record<string, unknown>): void {
21	  // Caller fields are nested under `data`, so one named `severity` cannot overwrite the line's own.
22	  const line = {
23	    severity: level,
24	    message,
25	    timestamp: new Date().toISOString(),
26	    category,
27	    ...(fields ? {data: fields} : {}),
28	  };
29	
30	  // ERROR to stderr: a stream that cannot be split by severity cannot be alerted on.
31	  // eslint-disable-next-line no-console -- the one place this package writes to a stream
32	  (level === 'ERROR' ? console.error : console.log)(serialise(line));
33	}
34	
35	// A throw here would take down the call site being observed, so an unserialisable field costs that field alone.
36	function serialise(line: Record<string, unknown>): string {
37	  const whole = probe(() => JSON.stringify(line));
38	  if (whole.ok) return whole.value;
39	
40	  // String() runs the caller's toString, so it is attempted inside the probe rather than before it.
41	  const degraded = probe(() =>
42	    JSON.stringify({
43	      severity: line.severity,
44	      message: String(line.message),
45	      timestamp: line.timestamp,
46	      category: String(line.category),
47	      data: `${UNSERIALISABLE}: ${whole.reason}`,
48	    })
49	  );
50	  if (degraded.ok) return degraded.value;
51	
52	  // Nothing the caller supplied survives into this one, so it cannot fail in turn.
53	  return JSON.stringify({
54	    severity: line.severity,
55	    message: UNSERIALISABLE,
56	    timestamp: line.timestamp,
57	    category: UNSERIALISABLE,
58	    data: `${UNSERIALISABLE}: ${degraded.reason}`,
59	  });
60	}
61	
62	// A probe, not control flow: it reports what happened rather than branching on a swallowed error.
63	function probe(run: () => string): {ok: true; value: string} | {ok: false; reason: string} {
64	  try {
65	    return {ok: true, value: run()};
66	  } catch (error) {
67	    const reason = error instanceof Error ? error.message : String(error);
68	    return {ok: false, reason: reason.split('\n')[0]};
69	  }
70	}
71	
72	const consoleLogger: Logger = {
73	  debug: (category: string, message: string, fields?: Record<string, unknown>) =>
74	    emit('DEBUG', category, message, fields),
75	  info: (category: string, message: string, fields?: Record<string, unknown>) =>
76	    emit('INFO', category, message, fields),
77	  warn: (category: string, message: string, fields?: Record<string, unknown>) =>
78	    emit('WARN', category, message, fields),
79	  error: (category: string, message: string, fields?: Record<string, unknown>) =>
80	    emit('ERROR', category, message, fields),
81	};
82	
83	let active: Logger = consoleLogger;
84	
85	// Process-global by design: every module that logs imports `log` at module scope, so there is one.
86	export function setLogger(logger?: Logger): void {
87	  // Handed `log` itself, the delegate below would call itself until the stack ran out, so that reads as none.
88	  active = logger === undefined || logger === log ? consoleLogger : logger;
89	}
90	
91	// The one place a level is tested, so LOG_LEVEL gates a supplied logger exactly as it gates the built-in one.
92	function dispatch(level: LevelName, category: string, message: string, fields?: Record<string, unknown>): void {
93	  if (LOG_LEVELS[level] < resolvedLevel) return;
94	
95	  const delivered = probe(() => {
96	    active[METHODS[level]](category, message, fields);
97	    return '';
98	  });
99	  if (delivered.ok) return;
100	
101	  // A supplied logger that throws must not take down the call site it observes, and the line is not dropped.
102	  probe(() => {
103	    emit(level, category, message, fields);
104	    return '';
105	  });
106	}
107	
108	// Delegating rather than reassigned, so a module that imported `log` before the swap still sees it.
109	export const log: Logger = {
110	  debug: (category: string, message: string, fields?: Record<string, unknown>) =>
111	    dispatch('DEBUG', category, message, fields),
112	  info: (category: string, message: string, fields?: Record<string, unknown>) =>
113	    dispatch('INFO', category, message, fields),
114	  warn: (category: string, message: string, fields?: Record<string, unknown>) =>
115	    dispatch('WARN', category, message, fields),
116	  error: (category: string, message: string, fields?: Record<string, unknown>) =>
117	    dispatch('ERROR', category, message, fields),
118	};
